""" Matches the given dtype to its pandas equivalent, if one exists

    Args:
        dtype (str): The type to attempt to match

    Returns:
        The pandas version of the dtype if one exists, otherwise the original
    """
def dtype_to_pandas_dtype(dtype: str) -> str {
    if (dtype == "integer") {
        dtype = "int";
    } elif (dtype == "string") {
        dtype = "str";
    } elif (dtype == "boolean") {
        dtype = "bool";
    }
    return dtype;
}

"""
    Helper function to round a given value to a specific precision, for example *.5
    So 5.4 will be rounded to 5.5
    """
def round_to_decimal(value: Any, precision: float = 0.5) -> float {
    return round((precision * round((float(value) / precision))), 1);
}

